197	pub(crate) fn convert_math_to_nodes(
198	    item: MathItem,
199	    engine: &mut Engine,
200	    styles: StyleChain,
201	    block: bool,
202	) -> SourceResult<Vec<Content>> {
203	    let mut ctx = MathContext::new(engine, styles, block);
