207	/// Collapses a collection of nodes into a single node, wrapping multiple nodes
208	/// in an `mrow`.
209	trait ContentExt {
210	    fn into_content(self) -> Content;
211	}
212	
213	impl ContentExt for Vec<Content> {
214	    fn into_content(self) -> Content {
215	        if self.len() == 1 {
216	            self.into_iter().next().unwrap()
217	        } else {
218	            HtmlElem::new(tag::mrow)
219	                .with_body(Some(Content::sequence(self)))
220	                .pack()
221	        }
222	    }
223	}
