225	/// Where an item sits among its siblings. Used to derive the default operator
226	/// form for an `mo`.
227	#[derive(Copy, Clone)]
228	enum NodePosition {
229	    Start,
230	    Middle,
231	    End,
232	    /// A lone item, with an optional explicit form given.
233	    Only(Option<Form>),
234	}
235	
236	impl NodePosition {
237	    fn get_form(self) -> Form {
238	        match self {
239	            Self::Start => Form::Prefix,
240	            Self::Middle => Form::Infix,
241	            Self::End => Form::Postfix,
242	            Self::Only(form) => form.unwrap_or(Form::Infix),
243	        }
244	    }
245	}
