283	/// The MathML Core CSS properties currently in effect.
284	///
285	/// Tracked so children only emit attributes that differ from what the browser
286	/// will apply via the UA styelsheet and our stylesheet.
287	#[derive(Copy, Clone, PartialEq)]
288	struct CssContext {
289	    math_style: MathStyle,
290	    math_shift: MathShift,
291	    math_depth: u32,
292	}
293	
294	impl CssContext {
295	    fn new(block: bool) -> Self {
296	        Self {
297	            math_style: if block { MathStyle::Normal } else { MathStyle::Compact },
298	            math_shift: MathShift::Normal,
299	            math_depth: 0,
300	        }
301	    }
302	
303	    fn depth_auto_add(self) -> Self {
304	        Self {
305	            math_depth: if self.math_style == MathStyle::Compact {
306	                self.math_depth + 1
307	            } else {
308	                self.math_depth
309	            },
310	            ..self
311	        }
312	    }
313	
314	    fn depth_add(self, n: u32) -> Self {
315	        Self { math_depth: self.math_depth + n, ..self }
316	    }
317	
318	    fn style_compact(self) -> Self {
319	        Self { math_style: MathStyle::Compact, ..self }
320	    }
321	
322	    fn shift_compact(self) -> Self {
323	        Self { math_shift: MathShift::Compact, ..self }
324	    }
325	
326	    fn from(size: MathSize, cramped: bool) -> Self {
327	        let math_shift = if cramped { MathShift::Compact } else { MathShift::Normal };
328	        match size {
329	            MathSize::Display => Self {
330	                math_style: MathStyle::Normal,
331	                math_shift,
332	                math_depth: 0,
333	            },
334	            MathSize::Text => Self {
335	                math_style: MathStyle::Compact,
336	                math_shift,
337	                math_depth: 0,
338	            },
339	            MathSize::Script => Self {
340	                math_style: MathStyle::Compact,
341	                math_shift,
342	                math_depth: 1,
343	            },
344	            MathSize::ScriptScript => Self {
345	                math_style: MathStyle::Compact,
346	                math_shift,
347	                math_depth: 2,
348	            },
349	        }
350	    }
351	}
