353	/// The context for math handling.
354	struct MathContext<'v, 'e> {
355	    engine: &'v mut Engine<'e>,
356	    content: Vec<Content>,
357	    embellishment: Option<EmbellishmentContext>,
358	    css: CssContext,
359	    trunk_depth: usize,
360	}
361	
362	impl<'v, 'e> MathContext<'v, 'e> {
363	    /// Create a new math context.
364	    fn new(engine: &'v mut Engine<'e>, styles: StyleChain, block: bool) -> Self {
365	        Self {
366	            engine,
367	            content: Vec::new(),
368	            embellishment: None,
369	            css: CssContext::new(block),
370	            trunk_depth: styles.links().count(),
371	        }
372	    }
373	
374	    /// Build a text element with the given diverging styles (relative to the
375	    /// equation's trunk). This is so that show rules aren't applied again to
376	    /// this text when the result html elements are realized again.
377	    fn body_text(&self, text: EcoString, span: Span, styles: StyleChain) -> Content {
378	        self.apply_diverging(TextElem::packed(text).spanned(span), styles)
379	    }
380	
381	    /// Apply the diverging styles (relative to the equation's trunk) to the
382	    /// given content. This is so that show rules on `html.elem` see the styles
383	    /// that were active during math realization.
384	    fn apply_diverging(&self, content: Content, styles: StyleChain) -> Content {
385	        content.styled_with_map(styles.suffix(self.trunk_depth))
386	    }
387	
388	    /// Push a node.
389	    fn push(&mut self, content: Content) {
390	        self.content.push(content);
391	    }
392	
393	    /// Run `f` with the CSS context temporarily replaced.
394	    fn with_css<T>(&mut self, css: CssContext, f: impl FnOnce(&mut Self) -> T) -> T {
395	        let prev = std::mem::replace(&mut self.css, css);
396	        let result = f(self);
397	        self.css = prev;
398	        result
399	    }
400	
401	    /// Run `f` with the trunk depth temporarily replaced.
402	    fn with_trunk_depth<T>(
403	        &mut self,
404	        trunk_depth: usize,
405	        f: impl FnOnce(&mut Self) -> T,
406	    ) -> T {
407	        let prev = std::mem::replace(&mut self.trunk_depth, trunk_depth);
408	        let result = f(self);
409	        self.trunk_depth = prev;
410	        result
411	    }
412	
413	    /// Handle the given item and return the resulting nodes, using `only` as
414	    /// the operator form preference if the item turns out to be lone.
415	    fn handle_into_nodes_with_only_form(
416	        &mut self,
417	        item: &MathItem,
418	        only: Option<Form>,
419	    ) -> SourceResult<Vec<Content>> {
420	        let prev = std::mem::take(&mut self.content);
421	        self.handle_into_self(item, only)?;
422	        Ok(std::mem::replace(&mut self.content, prev))
423	    }
424	
425	    /// Handle the given item and return the resulting nodes.
426	    fn handle_into_nodes(&mut self, item: &MathItem) -> SourceResult<Vec<Content>> {
427	        self.handle_into_nodes_with_only_form(item, None)
428	    }
429	
430	    /// Handle the given item and collapse the resulting nodes into a single
431	    /// node.
432	    fn handle_into_node(&mut self, item: &MathItem) -> SourceResult<Content> {
433	        Ok(self.handle_into_nodes(item)?.into_content())
434	    }
435	
436	    /// Handle the given item and collapse the resulting nodes into a single
437	    /// node, using `only` as the operator form preference if the item turns
438	    /// out to be lone.
439	    fn handle_into_node_with_only_form(
440	        &mut self,
441	        item: &MathItem,
442	        only: Form,
443	    ) -> SourceResult<Content> {
444	        Ok(self
445	            .handle_into_nodes_with_only_form(item, Some(only))?
446	            .into_content())
447	    }
448	
449	    /// Handle the given item as a lone child and strip form/spacing attributes
450	    /// from a resulting bare `mo`.
451	    ///
452	    /// This is for attachments in MathML, where a lone `mo` would otherwise
453	    /// get form `postfix` and have its `lspace`/`rspace` ignored. See
454	    /// [§ 3.3.1.2 Layout of `<mrow>`][layout].
455	    ///
456	    /// [layout]: https://www.w3.org/TR/mathml-core/#layout-of-mrow
457	    fn handle_into_node_lone(&mut self, item: &MathItem) -> SourceResult<Content> {
458	        Ok(strip_inert_mo_attrs(
459	            self.handle_into_node_with_only_form(item, Form::Postfix)?,
460	        ))
461	    }
462	
463	    /// Dispatch each child to the element handler, tagging it with its
464	    /// position among siblings. For a single-child item, `only` is the form
465	    /// preference.
466	    fn handle_into_self(
467	        &mut self,
468	        item: &MathItem,
469	        only: Option<Form>,
470	    ) -> SourceResult<()> {
471	        let items = item.as_slice();
472	        let len = items.len();
473	        for (i, item) in items.iter().enumerate() {
474	            let position = if len == 1 {
475	                NodePosition::Only(only)
476	            } else if i == 0 {
477	                NodePosition::Start
478	            } else if i == len - 1 {
479	                NodePosition::End
480	            } else {
481	                NodePosition::Middle
482	            };
483	            handle_realized(item, self, position)?;
484	        }
485	
486	        Ok(())
487	    }
488	}
489	
490	/// Handles a leaf element resulting from realization.
491	fn handle_realized(
492	    item: &MathItem,
493	    ctx: &mut MathContext,
494	    position: NodePosition,
495	) -> SourceResult<()> {
496	    // Handle non-component items first.
497	    let comp = match item {
498	        MathItem::Component(comp) => comp,
499	        MathItem::Spacing(amount, _, _) => {
500	            ctx.push(
501	                HtmlElem::new(tag::mspace)
502	                    .with_attr(attr::width, amount.to_css(()))
503	                    .pack(),
504	            );
505	            return Ok(());
506	        }
507	        MathItem::Space => {
508	            // We hard-code the space width as `(4/18)em`.
509	            ctx.push(
510	                HtmlElem::new(tag::mspace)
511	                    .with_attr(attr::width, SPACE_WIDTH.to_css(()))
512	                    .pack(),
513	            );
514	            return Ok(());
515	        }
516	        MathItem::Tag(tag) => {
517	            ctx.push(TagElem::new(tag.clone()).pack());
518	            return Ok(());
519	        }
520	    };
521	
522	    let props = &comp.props;
523	    let styles = comp.styles;
524	    let embellished = is_embellished_operator(item);
525	
526	    let target = CssContext::from(props.size, props.cramped);
527	    // We clamp the tracked depth at 2 so we don't emit unnecessary
528	    // `scriptlevel="2"` everywhere.
529	    let scriptlevel = (target.math_depth != ctx.css.math_depth.min(2))
530	        .then(|| eco_format!("{}", target.math_depth));
531	    let displaystyle = (target.math_style != ctx.css.math_style)
532	        .then(|| eco_format!("{}", target.math_style == MathStyle::Normal));
533	    let mut properties = css::Properties::new();
534	    if target.math_shift != ctx.css.math_shift {
535	        properties.push("math-shift", target.math_shift.to_string());
536	    }
537	
538	    // Push explicit lspace if it won't be added to the attributes of an `mo`.
539	    if !embellished
540	        && let Some(lspace) = props.lspace
541	        && !props.align_form_infix
542	        && !lspace.is_zero()
543	    {
544	        ctx.push(
545	            HtmlElem::new(tag::mspace)
546	                .with_attr(attr::width, eco_format!("{}em", lspace.get()))
547	                .with_optional_attr(attr::scriptlevel, scriptlevel.clone())
548	                .pack(),
549	        );
550	    }
551	
552	    // For embellished operators which aren't an `mo` element, pass the outer
553	    // spacing and position to the core operator.
554	    if embellished
555	        && !matches!(comp.kind, MathKind::Glyph(_) | MathKind::Text(_))
556	        && ctx.embellishment.is_none()
557	        && !props.align_form_infix
558	    {
559	        ctx.embellishment = Some(EmbellishmentContext {
560	            lspace: props.lspace,
561	            rspace: props.rspace,
562	            position,
563	            limits: has_limits(item),
564	        });
565	    }
566	
567	    let css = if target != ctx.css { target } else { ctx.css };
568	    let trunk_depth = styles.links().count();
569	    // Element's own context, established by the attributes emitted on it below.
570	    if let Some(mut node) = ctx.with_css(css, |ctx| -> SourceResult<Option<Content>> {
571	        ctx.with_trunk_depth(trunk_depth, |ctx| {
572	            Ok(match &comp.kind {
573	                MathKind::Glyph(item) => {
574	                    Some(handle_glyph(item, ctx, props, position, styles)?)
575	                }
576	                MathKind::Radical(item) => Some(handle_radical(item, ctx, props)?),
577	                MathKind::Accent(item) => Some(handle_accent(item, ctx, props)?),
578	                MathKind::Scripts(item) => Some(handle_scripts(item, ctx, props)?),
579	                MathKind::Primes(item) => {
580	                    Some(handle_primes(item, ctx, props, position, styles)?)
581	                }
582	                MathKind::Table(item) => Some(handle_table(item, ctx, props)?),
583	                MathKind::Fraction(item) => Some(handle_fraction(item, ctx, props)?),
584	                MathKind::Text(item) => {
585	                    Some(handle_text(item, ctx, props, position, styles)?)
586	                }
587	                MathKind::Number(item) => Some(handle_number(item, ctx, props, styles)?),
588	                MathKind::Fenced(item) => Some(handle_fenced(item, ctx, props)?),
589	                MathKind::Group(_) => Some(ctx.handle_into_node(item)?),
590	                MathKind::Multiline(item) => Some(handle_multiline(item, ctx, props)?),
591	                MathKind::Mathml(item) => Some(handle_mathml(item, ctx, props)?),
592	
593	                // Polyfill required for MathML Core.
594	                MathKind::SkewedFraction(item) => Some(ignored_math_item(
595	                    ctx,
596	                    &item.numerator,
597	                    props.span,
598	                    "skewed fraction",
599	                )?),
600	                MathKind::Line(item) if matches!(item.position, Position::Above) => {
601	                    Some(ignored_math_item(ctx, &item.base, props.span, "overline")?)
602	                }
603	                MathKind::Line(item) => {
604	                    Some(ignored_math_item(ctx, &item.base, props.span, "underline")?)
605	                }
606	                MathKind::Cancel(item) => {
607	                    Some(ignored_math_item(ctx, &item.base, props.span, "cancel")?)
608	                }
609	
610	                // TODO: enforce phrasing content.
611	                //
612	                // Arbitrary content is not allowed, as per the HTML spec. Only
613	                // MathML token elements (mi, mo, mn, ms, and mtext), when
614	                // descendants of HTML elements, may contain phrasing content
615	                // from the HTML namespace. See
616	                // https://html.spec.whatwg.org/#phrasing-content-2
617	                //
618	                // In MathML 3, nothing is allowed except MathML elements.
619	                // Further, nesting root-level math elements is disallowed.
620	                // Since the math element is considered phrasing content, it
621	                // can be nested in MathML Core (as long as it is itself within
622	                // a MathML token element).
623	                MathKind::Box(item) => Some(item.elem.clone().pack()),
624	                MathKind::External(item) => Some(item.content.clone()),
625	            })
626	        })
627	    })? {
628	        let modified = modify_inner_html_elem(&mut node, |elem| {
629	            elem.with_optional_attr(attr::scriptlevel, scriptlevel.clone())
630	                .with_optional_attr(attr::displaystyle, displaystyle)
631	                .with_css(properties)
632	        });
633	        ctx.push(if modified { ctx.apply_diverging(node, styles) } else { node });
634	    }
635	
636	    // Push explicit rspace if it won't be added to the attributes of an `mo`.
637	    if !embellished
638	        && let Some(rspace) = props.rspace
639	        && !rspace.is_zero()
640	    {
641	        ctx.push(
642	            HtmlElem::new(tag::mspace)
643	                .with_attr(attr::width, eco_format!("{}em", rspace.get()))
644	                .with_optional_attr(attr::scriptlevel, scriptlevel)
645	                .pack(),
646	        );
647	    }
648	
649	    Ok(())
650	}
