737	fn handle_glyph(
738	    item: &GlyphItem,
739	    ctx: &mut MathContext,
740	    props: &MathProperties,
741	    position: NodePosition,
742	    styles: StyleChain,
743	) -> SourceResult<Content> {
744	    let text = &item.text;
745	
746	    // Prime and factorial characters have math class Normal but are
747	    // semantically postfix operators, so emit `mo`. But only do this when the
748	    // math class hasn't been explicitly set by the user to something else.
749	    if props.class() == MathClass::Normal && (is_prime(text) || text == "!") {
750	        return Ok(make_mo(
751	            text,
752	            props.span,
753	            ctx,
754	            props,
755	            position,
756	            Some(Form::Postfix),
757	            false,
758	            false,
759	            false,
760	            None,
761	            styles,
762	        ));
763	    }
764	
765	    let mut form = None;
766	    let mut fence = false;
767	    let mut separator = false;
768	    let mut largeop = false;
769	    match props.class() {
770	        MathClass::Normal
771	        | MathClass::Alphabetic
772	        | MathClass::Special
773	        | MathClass::GlyphPart
774	        | MathClass::Space => {
775	            let mathvariant = will_auto_transform(text).then_some("normal");
776	            return Ok(HtmlElem::new(tag::mi)
777	                .with_body(Some(ctx.body_text(text.clone(), props.span, styles)))
778	                .with_optional_attr(attr::mathvariant, mathvariant)
779	                .pack());
780	        }
781	        MathClass::Diacritic => form = Some(Form::Postfix),
782	        MathClass::Binary | MathClass::Relation => form = Some(Form::Infix),
783	        MathClass::Vary | MathClass::Unary => form = Some(Form::Prefix),
784	        MathClass::Punctuation => separator = true,
785	        MathClass::Fence => fence = true,
786	        MathClass::Large => {
787	            largeop = item.class == MathClass::Large;
788	            form = Some(Form::Prefix);
789	        }
790	        MathClass::Opening => {
791	            fence = true;
792	            form = Some(Form::Prefix);
793	        }
794	        MathClass::Closing => {
795	            fence = true;
796	            form = Some(Form::Postfix);
797	        }
798	    }
799	
800	    Ok(make_mo(
801	        text,
802	        props.span,
803	        ctx,
804	        props,
805	        position,
806	        form,
807	        fence,
808	        separator,
809	        largeop,
810	        Some(item.stretch.get()),
811	        styles,
812	    ))
813	}
