815	fn handle_accent(
816	    item: &AccentItem,
817	    ctx: &mut MathContext,
818	    _props: &MathProperties,
819	) -> SourceResult<Content> {
820	    let (tag, attr, css) = if item.position == Position::Below {
821	        (tag::munder, attr::accentunder, ctx.css)
822	    } else {
823	        (tag::mover, attr::accent, ctx.css.shift_compact())
824	    };
825	
826	    // UA stylesheet.
827	    let base = ctx.with_css(css, |ctx| ctx.handle_into_node(&item.base))?;
828	
829	    // Firefox seems to be the only browser that applies the `dtls` OpenType
830	    // feature for the base of accents by default. We use our own CSS to force
831	    // enable/disable it on all browsers.
832	    let dotted =
833	        (!item.exact_frame_width && item.position == Position::Above && !item.dotless)
834	            .then_some("dotted");
835	
836	    // Whilst the validator https://validator.w3.org/nu/#file warns "Text run
837	    // starts with a composing character", using non-combining characters isn't
838	    // possible at the moment as not all accents have a non-combining
839	    // equivalent and the display of them is bad in browsers.
840	    // See https://github.com/w3c/mathml-core/issues/311.
841	    let accent = ctx.handle_into_node_lone(&item.accent)?;
842	
843	    Ok(HtmlElem::new(tag)
844	        .with_body(Some(base + accent))
845	        .with_attr(attr, "true")
846	        .with_optional_attr(crate::attr::class, dotted)
847	        .pack())
848	}
