850	fn handle_scripts(
851	    item: &ScriptsItem,
852	    ctx: &mut MathContext,
853	    _props: &MathProperties,
854	) -> SourceResult<Content> {
855	    let mut base = ctx.handle_into_node(&item.base)?;
856	
857	    // UA stylesheet + Typst stylesheet making bottom attachments cramped.
858	    let sup_css = ctx.css.depth_add(1).style_compact();
859	    let sub_css = sup_css.shift_compact();
860	
861	    macro_rules! handle {
862	        ($content:ident, $css:ident) => {
863	            item.$content
864	                .as_ref()
865	                .map(|x| ctx.with_css($css, |ctx| ctx.handle_into_node_lone(x)))
866	                .transpose()?
867	        };
868	    }
869	
870	    let t = handle!(top, sup_css);
871	    let tr = handle!(top_right, sup_css);
872	    let tl = handle!(top_left, sup_css);
873	    let b = handle!(bottom, sub_css);
874	    let br = handle!(bottom_right, sub_css);
875	    let bl = handle!(bottom_left, sub_css);
876	
877	    if let Some((tag, other_children)) = match (tl, tr, bl, br) {
878	        (None, None, None, None) => None,
879	        (None, None, None, Some(br)) => Some((tag::msub, vec![br])),
880	        (None, Some(tr), None, None) => Some((tag::msup, vec![tr])),
881	        (None, Some(tr), None, Some(br)) => Some((tag::msubsup, vec![br, tr])),
882	        (tl, tr, bl, br) => {
883	            let unwrap =
884	                |node: Option<Content>| node.unwrap_or(HtmlElem::new(tag::mrow).pack());
885	            Some((
886	                tag::mmultiscripts,
887	                vec![
888	                    unwrap(br),
889	                    unwrap(tr),
890	                    HtmlElem::new(tag::mprescripts).pack(),
891	                    unwrap(bl),
892	                    unwrap(tl),
893	                ],
894	            ))
895	        }
896	    } {
897	        let mut children = vec![base];
898	        children.extend(other_children);
899	        base = HtmlElem::new(tag).with_body(Some(Content::sequence(children))).pack();
900	    }
901	
902	    if let Some((tag, other_children)) = match (t, b) {
903	        (None, None) => None,
904	        (Some(t), None) => Some((tag::mover, eco_vec![t])),
905	        (None, Some(b)) => Some((tag::munder, eco_vec![b])),
906	        (Some(t), Some(b)) => Some((tag::munderover, eco_vec![b, t])),
907	    } {
908	        let mut children = vec![base];
909	        children.extend(other_children);
910	        base = HtmlElem::new(tag).with_body(Some(Content::sequence(children))).pack();
911	    }
912	
913	    Ok(base)
914	}
