916	fn handle_table(
917	    item: &TableItem,
918	    ctx: &mut MathContext,
919	    _props: &MathProperties,
920	) -> SourceResult<Content> {
921	    let (ncols, has_sub_cols) = item
922	        .cells
923	        .first()
924	        .map_or((0, false), |row| (row.len(), row.iter().any(|cell| cell.len() > 1)));
925	
926	    // Typst stylesheet.
927	    let css = ctx.css.depth_auto_add().style_compact().shift_compact();
928	    let cells = item
929	        .cells
930	        .iter()
931	        .map(|row| {
932	            let nodes = row
933	                .iter()
934	                .flat_map(|cell| {
935	                    cell.iter().enumerate().map(|(i, sub_col)| (i, cell.len(), sub_col))
936	                })
937	                .map(|(i, count, sub_col)| {
938	                    Ok(HtmlElem::new(tag::mtd)
939	                        .with_body(Some(Content::sequence(
940	                            ctx.with_css(css, |ctx| ctx.handle_into_nodes(sub_col))?,
941	                        )))
942	                        .with_optional_attr(
943	                            crate::attr::class,
944	                            table_mtd_class(i, count, ncols, item.alternator),
945	                        )
946	                        .pack())
947	                })
948	                .collect::<SourceResult<Vec<Content>>>()?;
949	            Ok(HtmlElem::new(tag::mtr)
950	                .with_body(Some(Content::sequence(nodes)))
951	                .pack())
952	        })
953	        .collect::<SourceResult<Vec<Content>>>()?;
954	
955	    let class = match (item.alternator, item.align) {
956	        (LeftRightAlternator::None, _) if ncols == 1 => Some(CASES_CLASS),
957	        (LeftRightAlternator::Right, _) if ncols == 1 && has_sub_cols => {
958	            Some(ALIGNED_CLASS)
959	        }
960	        (_, FixedAlignment::Start) => Some(LEFT_ALIGN_CLASS),
961	        (_, FixedAlignment::End) => Some(RIGHT_ALIGN_CLASS),
962	        (_, FixedAlignment::Center) => None,
963	    };
964	
965	    Ok(HtmlElem::new(tag::mtable)
966	        .with_body(Some(Content::sequence(cells)))
967	        .with_optional_attr(crate::attr::class, class)
968	        .pack())
969	}
