1033	fn handle_fenced(
1034	    item: &FencedItem,
1035	    ctx: &mut MathContext,
1036	    _props: &MathProperties,
1037	) -> SourceResult<Content> {
1038	    let mut children = Vec::new();
1039	    if let Some(open) = item
1040	        .open
1041	        .as_ref()
1042	        .map(|x| ctx.handle_into_node_with_only_form(x, Form::Prefix))
1043	        .transpose()?
1044	    {
1045	        children.push(open);
1046	    }
1047	    let body = ctx.handle_into_node(&item.body)?;
1048	    children.push(body);
1049	    if let Some(close) = item
1050	        .close
1051	        .as_ref()
1052	        .map(|x| ctx.handle_into_node_with_only_form(x, Form::Postfix))
1053	        .transpose()?
1054	    {
1055	        children.push(close);
1056	    }
1057	
1058	    // We shouldn't always need to wrap this in an `mrow`, but browsers don't
1059	    // follow the spec and insert an inferred `mrow` in situations like
1060	    // `<msqrt>...</msqrt>`, `<mtd>...</mtd>`, and the top-level
1061	    // `<math>...</math>`. For example:
1062	    // https://bugzilla.mozilla.org/show_bug.cgi?id=236963
1063	    // https://bugzilla.mozilla.org/show_bug.cgi?id=2018403
1064	    Ok(HtmlElem::new(tag::mrow)
1065	        .with_body(Some(Content::sequence(children)))
1066	        .pack())
1067	}
