1084	/// Creates an `mo` element.
1085	#[expect(clippy::too_many_arguments)]
1086	fn make_mo(
1087	    text: &str,
1088	    span: Span,
1089	    ctx: &mut MathContext,
1090	    props: &MathProperties,
1091	    position: NodePosition,
1092	    mut form: Option<Form>,
1093	    fence: bool,
1094	    separator: bool,
1095	    largeop: bool,
1096	    stretch: Option<Stretch>,
1097	    styles: StyleChain,
1098	) -> Content {
1099	    // If this is the core operator of an embellished operator, use the spacing
1100	    // and position stored in the context.
1101	    let (mut lspace, rspace, position, limits) = ctx
1102	        .embellishment
1103	        .take()
1104	        .map(|e| (e.lspace, e.rspace, e.position, e.limits))
1105	        .unwrap_or((props.lspace, props.rspace, position, false));
1106	
1107	    if props.align_form_infix {
1108	        form = Some(Form::Infix);
1109	        // The lspace at this stage is gone, but since it is infix the spacing
1110	        // is symmetric, so we can just use the rspace.
1111	        lspace = rspace;
1112	    }
1113	
1114	    let initial_form = position.get_form();
1115	    let info = OperatorInfo::of(
1116	        text,
1117	        form.unwrap_or(initial_form),
1118	        form.is_some_and(|f| f != initial_form),
1119	    );
1120	
1121	    // We force emitting `lspace` and `rspace` for a fraction slash (for
1122	    // horizontal style) as it renders in browsers with spacing around it.
1123	    // Browsers haven't updated the operator dictionary. See
1124	    // https://phabricator.wikimedia.org/T375337
1125	    // https://github.com/w3c/mathml-core/issues/260
1126	    // https://github.com/w3c/mathml-core/pull/265
1127	    // https://issues.chromium.org/issues/414588528
1128	    // https://bugzilla.mozilla.org/show_bug.cgi?id=1586575
1129	    let force_space = text == "/" && form.unwrap_or(initial_form) == Form::Infix;
1130	
1131	    let form = form.filter(|f| *f != initial_form).map(|f| match f {
1132	        Form::Prefix => "prefix",
1133	        Form::Infix => "infix",
1134	        Form::Postfix => "postfix",
1135	    });
1136	
1137	    let lspace = lspace.unwrap_or(Em::zero()).get();
1138	    let lspace =
1139	        (force_space || lspace != info.lspace).then(|| eco_format!("{lspace}em"));
1140	    let rspace = rspace.unwrap_or(Em::zero()).get();
1141	    let rspace =
1142	        (force_space || rspace != info.rspace).then(|| eco_format!("{rspace}em"));
1143	
1144	    let fence = (fence != is_fence(text)).then(|| eco_format!("{fence}"));
1145	    let separator = (separator != is_separator(text)).then(|| eco_format!("{separator}"));
1146	
1147	    let largeop = (largeop != info.properties.contains(Properties::LARGEOP))
1148	        .then(|| eco_format!("{largeop}"));
1149	
1150	    // In compact styles the browser will move top/bottom attachments to the tl
1151	    // and br positions, so we need to explicitly disable this.
1152	    let movablelimits = (limits
1153	        && ctx.css.math_style == MathStyle::Compact
1154	        && info.properties.contains(Properties::MOVABLELIMITS))
1155	    .then(|| eco_format!("false"));
1156	
1157	    let mut chars = text.chars();
1158	    let stretch_axis = if let Some(c) = chars.next()
1159	        && chars.next().is_none()
1160	        && is_stretch_axis_inline(c)
1161	    {
1162	        Axis::X
1163	    } else {
1164	        Axis::Y
1165	    };
1166	    let explicit = stretch.is_some_and(|stretch| stretch.is_explicit(stretch_axis));
1167	    let stretchy = (explicit != info.properties.contains(Properties::STRETCHY))
1168	        .then(|| eco_format!("{explicit}"));
1169	
1170	    // We don't need to set `maxsize` as it is infinity by default.
1171	    let (symmetric, minsize) = if explicit {
1172	        let symmetric = (stretch_axis == Axis::Y
1173	            && !info.properties.contains(Properties::SYMMETRIC))
1174	        .then(|| eco_format!("true"));
1175	
1176	        let minsize = stretch
1177	            .unwrap()
1178	            .resolve_requested(stretch_axis)
1179	            .map(|target| target.to_css(()));
1180	
1181	        (symmetric, minsize)
1182	    } else {
1183	        (None, None)
1184	    };
1185	
1186	    HtmlElem::new(tag::mo)
1187	        .with_body(Some(ctx.body_text(text.into(), span, styles)))
1188	        .with_optional_attr(attr::form, form)
1189	        .with_optional_attr(attr::fence, fence)
1190	        .with_optional_attr(attr::separator, separator)
1191	        .with_optional_attr(attr::lspace, lspace)
1192	        .with_optional_attr(attr::rspace, rspace)
1193	        .with_optional_attr(attr::stretchy, stretchy)
1194	        .with_optional_attr(attr::symmetric, symmetric)
1195	        .with_optional_attr(attr::minsize, minsize)
1196	        .with_optional_attr(attr::largeop, largeop)
1197	        .with_optional_attr(attr::movablelimits, movablelimits)
1198	        .pack()
1199	}
