1201	/// The class for an `mtd` that is one of multiple sub-columns in a table.
1202	fn table_mtd_class(
1203	    index: usize,
1204	    count: usize,
1205	    ncols: usize,
1206	    alternator: LeftRightAlternator,
1207	) -> Option<EcoString> {
1208	    if count <= 1 || ncols <= 1 || !matches!(alternator, LeftRightAlternator::Right) {
1209	        return None;
1210	    }
1211	
1212	    let mut class = EcoString::from(if index % 2 == 0 {
1213	        RIGHT_ALIGN_CLASS
1214	    } else {
1215	        LEFT_ALIGN_CLASS
1216	    });
1217	    class.push(' ');
1218	    if index == 0 {
1219	        class.push_str(RIGHT_FLUSH_CLASS);
1220	    } else if index + 1 == count {
1221	        class.push_str(LEFT_FLUSH_CLASS);
1222	    } else {
1223	        class.push_str(FLUSHED_CLASS);
1224	    }
1225	    Some(class)
1226	}
1227	
1228	/// Strips `form`, `lspace`, and `rspace` from a singleton `mo`.
1229	fn strip_inert_mo_attrs(mut node: Content) -> Content {
1230	    modify_inner_html_elem(&mut node, |mut elem| {
1231	        if elem.tag == tag::mo {
1232	            elem.attrs.as_option_mut().get_or_insert_default().0.retain(|(a, _)| {
1233	                *a != attr::form && *a != attr::lspace && *a != attr::rspace
1234	            });
1235	        }
1236	        elem
1237	    });
1238	    node
1239	}
1240	
1241	/// Modifies the inner [`HtmlElem`] of a content node, peeking through any
1242	/// outer [`StyledElem`] wrapper.
1243	///
1244	/// Returns `true` if a modification was made.
1245	fn modify_inner_html_elem(
1246	    content: &mut Content,
1247	    f: impl FnOnce(HtmlElem) -> HtmlElem,
1248	) -> bool {
1249	    if let Some(styled) = content.to_packed_mut::<StyledElem>() {
1250	        return modify_inner_html_elem(&mut styled.child, f);
1251	    }
1252	    if content.is::<HtmlElem>() {
1253	        let taken = std::mem::take(content);
1254	        *content = f(taken.into_packed::<HtmlElem>().unwrap().unpack()).pack();
1255	        return true;
1256	    }
1257	    false
1258	}
1259	
1260	/// Whether the text is one of the dedicated Unicode prime characters.
1261	fn is_prime(text: &str) -> bool {
1262	    let mut chars = text.chars();
1263	    let Some(c) = chars.next() else { return false };
1264	    chars.next().is_none() && matches!(c, '′' | '″' | '‴' | '⁗')
1265	}
1266	
1267	/// Whether this item is considered an embellished operator in MathML Core. See
1268	/// [§ 3.2.4.1 Embellished operators][embellished].
1269	///
1270	/// [embellished]: https://www.w3.org/TR/mathml-core/#embellished-operators
1271	fn is_embellished_operator(item: &MathItem) -> bool {
1272	    let MathItem::Component(comp) = item else { return false };
1273	    match &comp.kind {
1274	        MathKind::Glyph(_) => !matches!(
1275	            comp.props.class(),
1276	            MathClass::Normal
1277	                | MathClass::Alphabetic
1278	                | MathClass::Special
1279	                | MathClass::GlyphPart
1280	                | MathClass::Space
1281	        ),
1282	        MathKind::Text(_) => comp.props.class() == MathClass::Large,
1283	        MathKind::Scripts(scripts) => is_embellished_operator(&scripts.base),
1284	        MathKind::Accent(accent) => is_embellished_operator(&accent.base),
1285	        MathKind::Fraction(fraction) => is_embellished_operator(&fraction.numerator),
1286	        MathKind::Group(group) => {
1287	            let mut items = group
1288	                .items
1289	                .iter()
1290	                .filter(|item| !item.is_ignorant() && !is_space_like(item));
1291	            items.next().is_some_and(|item| is_embellished_operator(item))
1292	                && items.next().is_none()
1293	        }
1294	        _ => false,
1295	    }
1296	}
1297	
1298	/// Whether this item is considered a space-like element in MathML Core. See
1299	/// [§ 3.2.5.1 Definition of space-like elements][space].
1300	///
1301	/// [space]: https://www.w3.org/TR/mathml-core/#definition-of-space-like-elements
1302	fn is_space_like(item: &MathItem) -> bool {
1303	    match item {
1304	        MathItem::Spacing(..) | MathItem::Space => true,
1305	        MathItem::Component(comp) => match &comp.kind {
1306	            MathKind::Text(_) => comp.props.class() != MathClass::Large,
1307	            MathKind::Group(group) => group
1308	                .items
1309	                .iter()
1310	                .filter(|item| !item.is_ignorant())
1311	                .all(is_space_like),
1312	            _ => false,
1313	        },
1314	        MathItem::Tag(_) => false,
1315	    }
1316	}
1317	
1318	/// Whether this item, which is considered an embellished operator in MathML
1319	/// Core, has top or bottom attachements somewhere.
1320	fn has_limits(item: &MathItem) -> bool {
1321	    let MathItem::Component(comp) = item else { return false };
1322	    match &comp.kind {
1323	        MathKind::Glyph(_) => false,
1324	        MathKind::Text(_) => false,
1325	        MathKind::Scripts(scripts) => {
1326	            scripts.top.is_some() || scripts.bottom.is_some() || has_limits(&scripts.base)
1327	        }
1328	        MathKind::Accent(accent) => has_limits(&accent.base),
1329	        MathKind::Fraction(fraction) => has_limits(&fraction.numerator),
1330	        MathKind::Group(group) => group.items.iter().any(|item| has_limits(item)),
1331	        _ => false,
1332	    }
1333	}
1334	
1335	/// Warn on ignored math items, but still handle their main part.
1336	fn ignored_math_item(
1337	    ctx: &mut MathContext,
1338	    body: &MathItem,
1339	    span: Span,
1340	    name: &str,
1341	) -> SourceResult<Content> {
1342	    ctx.engine
1343	        .sink
1344	        .warn(warning!(span, "{name} was ignored during MathML export"));
1345	    ctx.handle_into_node(body)
1346	}
1347

